package com.ashkan.hotel;

import com.sun.net.httpserver.HttpExchange;
import java.io.*;
import java.math.*;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.*;

/** Commercial booking endpoints: room catalog, rate plans, availability and price quotes. */
final class CommercialApiV2 implements AutoCloseable {
    private final CommercialRepository repository; private final DynamicPricingEngine pricing=new DynamicPricingEngine();
    CommercialApiV2(String url,String user,String password,int pool){repository=new CommercialRepository(url,user,password,pool);}
    boolean supports(String path){return path.startsWith("/api/v2/rooms")||path.startsWith("/api/v2/rate-plans")||path.equals("/api/v2/availability")||path.equals("/api/v2/quotes");}
    void handle(HttpExchange x)throws IOException {
        try {
            String path=x.getRequestURI().getPath(), method=x.getRequestMethod();
            if(path.equals("/api/v2/rooms")){if("GET".equals(method)){send(x,200,Map.of("items",repository.rooms(query(x,"roomType")).stream().map(CommercialApiV2::roomMap).toList()));return;}if("POST".equals(method)){Map<String,Object>b=body(x);repository.saveRoom(new CommercialRepository.Room(str(b,"id",UUID.randomUUID().toString()),req(b,"roomType"),req(b,"roomNumber"),integer(b,"floor",1),integer(b,"capacity",2),str(b,"status","ACTIVE"),strings(b.get("amenities"))));send(x,201,Map.of("status","saved"));return;}}
            if(path.equals("/api/v2/rate-plans")){if("GET".equals(method)){send(x,200,Map.of("items",repository.ratePlans().stream().map(CommercialApiV2::rateMap).toList()));return;}if("POST".equals(method)){Map<String,Object>b=body(x);repository.saveRatePlan(new CommercialRepository.RatePlan(str(b,"id",UUID.randomUUID().toString()),req(b,"name"),req(b,"roomType"),str(b,"currency","EUR"),decimal(b,"baseRate","0"),decimal(b,"weekendMultiplier","1.15"),decimal(b,"highDemandMultiplier","1.25"),integer(b,"maxOccupancy",2),bool(b,"active",true),date(b,"validFrom"),date(b,"validTo")));send(x,201,Map.of("status","saved"));return;}}
            if(path.equals("/api/v2/availability")&&"GET".equals(method)){LocalDate from=LocalDate.parse(reqQuery(x,"checkIn")),to=LocalDate.parse(reqQuery(x,"checkOut"));if(!to.isAfter(from))throw new IllegalArgumentException("checkOut must be after checkIn");int guests=integer(query(x,"guests"),1);if(guests<1||guests>20)throw new IllegalArgumentException("guests must be between 1 and 20");send(x,200,repository.availability(reqQuery(x,"roomType"),from,to,guests));return;}
            if(path.equals("/api/v2/quotes")&&"POST".equals(method)){Map<String,Object>b=body(x);LocalDate from=LocalDate.parse(req(b,"checkIn")),to=LocalDate.parse(req(b,"checkOut"));if(!to.isAfter(from))throw new IllegalArgumentException("checkOut must be after checkIn");int guests=integer(b,"guests",1);CommercialRepository.RatePlan plan=repository.ratePlan(req(b,"ratePlanId"),from,to).orElseThrow(()->new IllegalArgumentException("Active rate plan not found for requested dates"));Map<String,Object> availability=repository.availability(plan.roomType(),from,to,guests);BigDecimal occupancy=(BigDecimal)availability.get("occupancyRatio");DynamicPricingEngine.Quote quote=pricing.quote(new DynamicPricingEngine.Rules(plan.baseRate(),plan.weekendMultiplier(),plan.highDemandMultiplier(),plan.currency(),plan.maxOccupancy()),from,to,guests,occupancy);Map<String,Object> response=new LinkedHashMap<>();response.put("ratePlanId",plan.id());response.put("roomType",plan.roomType());response.put("available",availability.get("available"));response.put("availability",availability);response.put("currency",quote.currency());response.put("numberOfNights",quote.numberOfNights());response.put("subtotal",quote.subtotal());response.put("total",quote.total());response.put("nights",quote.nights().stream().map(n->Map.of("date",n.date().toString(),"baseRate",n.baseRate(),"weekendFactor",n.weekendFactor(),"demandFactor",n.demandFactor(),"price",n.finalRate())).toList());send(x,200,response);return;}
            send(x,405,Map.of("error","method_not_allowed"));
        } catch(IllegalArgumentException e){send(x,400,Map.of("error","validation_failed","message",Objects.toString(e.getMessage(),"Invalid request")));}
          catch(java.sql.SQLException e){send(x,500,Map.of("error","commercial_operation_failed","message",Objects.toString(e.getMessage(),"Database operation failed")));}
          catch(Exception e){send(x,500,Map.of("error","commercial_operation_failed","message",Objects.toString(e.getMessage(),"Unexpected error")));}
    }
    private static Map<String,Object> roomMap(CommercialRepository.Room r){return Map.of("id",r.id(),"roomType",r.roomType(),"roomNumber",r.roomNumber(),"floor",r.floor(),"capacity",r.capacity(),"status",r.status(),"amenities",r.amenities());}
    private static Map<String,Object> rateMap(CommercialRepository.RatePlan r){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.id());m.put("name",r.name());m.put("roomType",r.roomType());m.put("currency",r.currency());m.put("baseRate",r.baseRate());m.put("weekendMultiplier",r.weekendMultiplier());m.put("highDemandMultiplier",r.highDemandMultiplier());m.put("maxOccupancy",r.maxOccupancy());m.put("active",r.active());m.put("validFrom",r.validFrom()==null?null:r.validFrom().toString());m.put("validTo",r.validTo()==null?null:r.validTo().toString());return m;}
    private static Map<String,Object> body(HttpExchange x)throws IOException{byte[] raw=x.getRequestBody().readNBytes(1_000_001);if(raw.length>1_000_000)throw new IllegalArgumentException("Request body too large");return ApiJson.object(new String(raw,StandardCharsets.UTF_8));}
    private static String query(HttpExchange x,String key){String q=x.getRequestURI().getRawQuery();if(q==null)return null;for(String pair:q.split("&")){String[]p=pair.split("=",2);if(URLDecoder.decode(p[0],StandardCharsets.UTF_8).equals(key))return p.length>1?URLDecoder.decode(p[1],StandardCharsets.UTF_8):"";}return null;}
    private static String reqQuery(HttpExchange x,String k){String v=query(x,k);if(v==null||v.isBlank())throw new IllegalArgumentException(k+" is required");return v;}
    private static String req(Map<String,Object>b,String k){String v=str(b,k,null);if(v==null||v.isBlank())throw new IllegalArgumentException(k+" is required");return v;}
    private static String str(Map<String,Object>b,String k,String d){return ApiJson.str(b,k,d);}private static BigDecimal decimal(Map<String,Object>b,String k,String d){return ApiJson.decimal(b,k,d);}private static int integer(Map<String,Object>b,String k,int d){Object v=b.get(k);try{return v==null?d:Integer.parseInt(String.valueOf(v));}catch(Exception e){throw new IllegalArgumentException(k+" must be an integer");}}private static int integer(String v,int d){try{return v==null?d:Integer.parseInt(v);}catch(Exception e){throw new IllegalArgumentException("Invalid integer query parameter");}}private static boolean bool(Map<String,Object>b,String k,boolean d){Object v=b.get(k);return v==null?d:Boolean.parseBoolean(String.valueOf(v));}private static LocalDate date(Map<String,Object>b,String k){String v=str(b,k,null);return v==null||v.isBlank()?null:LocalDate.parse(v);}private static List<String> strings(Object v){if(v==null)return List.of();if(!(v instanceof List<?> l))throw new IllegalArgumentException("amenities must be an array");return l.stream().map(String::valueOf).toList();}
    private static void send(HttpExchange x,int status,Object value)throws IOException{byte[] data=ApiJson.write(value).getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.getResponseHeaders().set("Cache-Control","no-store");x.getResponseHeaders().set("X-Hotel-Status",Integer.toString(status));x.sendResponseHeaders(status,data.length);try(OutputStream out=x.getResponseBody()){out.write(data);}}
    @Override public void close(){repository.close();}
}
